12	// Span tracks timing for an operation and its substeps.
13	// A Span is not safe for concurrent use from multiple goroutines.
14	type Span struct {
15		name       string
16		start      time.Time
17		parent     *Span
18		children   []*Span
19		duration   time.Duration
20		attrs      []slog.Attr
21		ctx        context.Context
22		ended      bool
23		err        error
24		isLoopIter bool
25	}
26	
27	// Start begins a new span. If ctx already has a span, the new one becomes a child.
28	// Returns the updated context and the span. Call span.End() when the operation completes.
29	func Start(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *Span) {
30		parent := spanFromContext(ctx)
31		s := &Span{
32			name:   name,
33			start:  time.Now(),
34			parent: parent,
35			attrs:  attrs,
36			ctx:    ctx,
37		}
38		if parent != nil {
39			parent.children = append(parent.children, s)
40		}
41		return contextWithSpan(ctx, s), s
42	}
43	
44	// RecordError marks the span as errored. Only the first non-nil error is stored;
45	// subsequent calls are no-ops. Call this before End() on error paths.
46	func (s *Span) RecordError(err error) {
47		if err == nil || s.err != nil {
48			return
49		}
50		s.err = err
51	}
52	
53	// End completes the span. For root spans, emits a single DEBUG log line
54	// with the full timing tree. For child spans, records the duration only.
55	// Safe to call multiple times -- subsequent calls are no-ops.
56	func (s *Span) End() {
57		if s.ended {
58			return
59		}
60		s.ended = true
61		s.duration = time.Since(s.start)
62	
63		// Only root spans emit log output
64		if s.parent != nil {
65			return
66		}
67	
68		logCtx := logging.WithComponent(s.ctx, "perf")
69		attrs := make([]any, 0, 3+len(s.attrs)+countChildStepAttrs(s))
70		attrs = append(attrs, slog.String("op", s.name))
71		attrs = append(attrs, slog.Int64("duration_ms", s.duration.Milliseconds()))
72		if s.err != nil {
73			attrs = append(attrs, slog.Bool("error", true))
74		}
75	
76		attrs = appendChildStepAttrs(attrs, s, "")
77	
78		for _, a := range s.attrs {
79			attrs = append(attrs, a)
80		}
81	
82		logging.Debug(logCtx, "perf", attrs...)
83	}
84	
85	// appendChildStepAttrs emits the full child timing tree under parent.
86	//
87	// Normal children use their span names, with ~N suffixes for duplicate sibling
88	// names. Loop iterations (from LoopSpan.Iteration) keep the historical numeric
89	// keys: steps.<loopName>.0_ms, steps.<loopName>.1_ms, etc.
90	func appendChildStepAttrs(attrs []any, parent *Span, parentKey string) []any {
91		seen := make(map[string]int, len(parent.children))
92		loopIndex := 0
93		for _, child := range parent.children {
94			if !child.ended {
95				child.End()
96			}
97	
98			var stepKey string
99			if child.isLoopIter && parentKey != "" {
100				stepKey = fmt.Sprintf("%s.%d", parentKey, loopIndex)
101				loopIndex++
102			} else {
103				stepKey = childStepKey(child.name, seen)
104				if parentKey != "" {
105					stepKey = parentKey + "." + stepKey
106				}
107			}
108	
109			attrs = append(attrs, slog.Int64("steps."+stepKey+"_ms", child.duration.Milliseconds()))
110			if child.err != nil {
111				attrs = append(attrs, slog.Bool("steps."+stepKey+"_err", true))
112			}
113	
114			attrs = appendChildStepAttrs(attrs, child, stepKey)
115		}
116		return attrs
117	}
118	
119	func countChildStepAttrs(parent *Span) int {
120		count := 0
121		for _, child := range parent.children {
122			count++
123			if child.err != nil {
124				count++
125			}
126			count += countChildStepAttrs(child)
127		}
128		return count
129	}
130	
131	// childStepKey returns a unique key for a child span name.
132	// First occurrence keeps the original name; subsequent get ~1, ~2, etc.
133	// Uses "~" separator to avoid collision with grandchild "." indexing
134	// (e.g. steps.foo.0_ms for loop iterations).
135	// The seen map is updated in place.
136	func childStepKey(name string, seen map[string]int) string {
137		n := seen[name]
138		seen[name] = n + 1
139		if n == 0 {
140			return name
141		}
142		return fmt.Sprintf("%s~%d", name, n)
143	}
144	
145	// LoopSpan wraps a Span that groups loop iterations. Each call to Iteration
146	// creates a child span representing one pass through the loop.
147	//
148	// Usage:
149	//
150	//	ctx, loop := perf.StartLoop(ctx, "process_sessions")
151	//	for _, item := range items {
152	//	    iterCtx, iterSpan := loop.Iteration(ctx)
153	//	    doWork(iterCtx, item)
154	//	    iterSpan.End()
155	//	}
156	//	loop.End()
157	type LoopSpan struct {
158		span *Span
159	}
160	
161	// StartLoop begins a new loop span. The returned context contains the loop span
162	// and should be passed to Iteration. Call loop.End() after the loop completes.
163	func StartLoop(ctx context.Context, name string, attrs ...slog.Attr) (context.Context, *LoopSpan) {
164		ctx, s := Start(ctx, name, attrs...)
165		return ctx, &LoopSpan{span: s}
166	}
167	
168	// Iteration creates a child span for a single loop iteration. The caller must
169	// call End() on the returned span when the iteration completes.
170	func (l *LoopSpan) Iteration(ctx context.Context) (context.Context, *Span) {
171		ctx, s := Start(ctx, l.span.name)
172		s.isLoopIter = true
173		return ctx, s
174	}
175	
176	// End completes the loop span, auto-ending any unended iteration children first
177	// so their durations are captured at loop-end time rather than deferring to the
178	// root span's End() (which may run much later).
179	func (l *LoopSpan) End() {
180		for _, child := range l.span.children {
181			if !child.ended {
182				child.End()
183			}
184		}
185		l.span.End()
186	}
