395	func migrateOneCheckpoint(ctx context.Context, repo *git.Repository, v1Store *checkpoint.GitStore, v2Store *checkpoint.V2GitStore, info checkpoint.CommittedInfo, force bool, fullArtifacts checkpoint.FullSessionArtifactsIndex) (*migratedFullCheckpoint, migrateCheckpointOutcome, error) {
396		var outcome migrateCheckpointOutcome
397	
398		existing, err := v2Store.ReadCommitted(ctx, info.CheckpointID)
399		if err != nil {
400			return nil, outcome, fmt.Errorf("failed to check v2 for checkpoint %s: %w", info.CheckpointID, err)
401		}
402	
403		if existing != nil && !force {
404			// Already in v2. Pack sessions whose /full/* artifacts are missing
405			// (resume an interrupted run) and backfill transcript.jsonl on /main
406			// where it's missing. With nothing to do on either front, return
407			// errAlreadyMigrated so the caller counts it as skipped.
408			fullCheckpoint, err := collectMissingFullCheckpointForPacking(ctx, repo, v1Store, v2Store, info, existing, fullArtifacts)
409			if err != nil && !errors.Is(err, errAlreadyMigrated) {
410				return nil, outcome, err
411			}
412			backfilled, backfillErr := backfillCompactTranscripts(ctx, v1Store, v2Store, info, existing)
413			if errors.Is(backfillErr, errTranscriptNotGeneratable) {
414				outcome.compactTranscriptSkipped = true
415			} else if backfillErr != nil && !errors.Is(backfillErr, errAlreadyMigrated) {
416				return nil, outcome, backfillErr
417			}
418			if fullCheckpoint == nil {
419				if backfilled > 0 {
420					return nil, outcome, nil
421				}
422				return nil, outcome, errAlreadyMigrated
423			}
424			return fullCheckpoint, outcome, nil
425		}
426	
427		if existing != nil && force {
428			if pruneErr := pruneV2CheckpointForForce(ctx, repo, v2Store, info.CheckpointID); pruneErr != nil {
429				return nil, outcome, fmt.Errorf("failed to reset existing v2 checkpoint %s before force migration: %w", info.CheckpointID, pruneErr)
430			}
431		}
432	
433		summary, err := v1Store.ReadCommitted(ctx, info.CheckpointID)
434		if err != nil {
435			return nil, outcome, fmt.Errorf("failed to read v1 summary: %w", err)
436		}
437		if summary == nil {
438			return nil, outcome, fmt.Errorf("v1 checkpoint %s has no summary", info.CheckpointID)
439		}
440	
441		compactFailed := false
442		shouldCopyTaskMetadata := false
443		skippedMissingSessions := 0
444		migratedSessions := 0
445		v1ToV2SessionIdx := make(map[int]int, len(summary.Sessions))
446		fullCheckpoint := &migratedFullCheckpoint{
447			checkpointID: info.CheckpointID,
448		}
449	
450		for sessionIdx := range len(summary.Sessions) {
451			content, skipped, readErr := readV1SessionForMigration(ctx, v1Store, info.CheckpointID, sessionIdx)
452			if skipped {
453				skippedMissingSessions++
454				outcome.missingSessions++
455				continue
456			}
457			if readErr != nil {
458				return nil, outcome, fmt.Errorf("failed to read v1 session %d: %w", sessionIdx, readErr)
459			}
460			if content.Metadata.IsTask {
461				shouldCopyTaskMetadata = true
462			}
463	
464			opts := buildMigrateWriteOpts(content, info, summary.CombinedAttribution)
465	
466			compacted := tryCompactTranscript(ctx, content.Transcript, content.Metadata)
467			if compacted != nil {
468				opts.CompactTranscript = compacted
469				opts.CompactTranscriptStart = computeCompactOffset(ctx, content.Transcript, compacted, content.Metadata)
470			} else if len(content.Transcript) > 0 {
471				compactFailed = true
472			}
473	
474			mainOpts := opts
475			mainOpts.Transcript = redact.AlreadyRedacted(nil)
476			v2SessionIdx, writeErr := v2Store.WriteCommittedWithSessionIndex(ctx, mainOpts)
477			if writeErr != nil {
478				return nil, outcome, fmt.Errorf("failed to write v2 session %d: %w", sessionIdx, writeErr)
479			}
480			v1ToV2SessionIdx[sessionIdx] = v2SessionIdx
481			fullCheckpoint.sessions = append(fullCheckpoint.sessions, migratedFullSession{
482				sessionIndex: v2SessionIdx,
483				content:      content,
484			})
485			migratedSessions++
486		}
487	
488		if migratedSessions == 0 {
489			return nil, outcome, fmt.Errorf("%w: v1 metadata lists %d session(s), but no transcript/session content exists for any of them", errNoMigratableSessions, len(summary.Sessions))
490		}
491	
492		if shouldCopyTaskMetadata {
493			taskTrees, taskErr := collectTaskMetadataForMigratedFullGeneration(repo, info.CheckpointID, summary, v1ToV2SessionIdx)
494			if taskErr != nil {
495				logging.Warn(ctx, "failed to copy task metadata to v2",
496					slog.String("checkpoint_id", string(info.CheckpointID)),
497					slog.String("error", taskErr.Error()),
498				)
499			} else {
500				fullCheckpoint.taskTrees = taskTrees
501			}
502		}
503	
504		if compactFailed {
505			outcome.compactTranscriptSkipped = true
506			logging.Warn(ctx, "compact transcript not generated during checkpoint migration",
507				slog.String("checkpoint_id", string(info.CheckpointID)),
508				slog.Int("migrated_sessions", migratedSessions),
509			)
510		}
511		if skippedMissingSessions > 0 {
512			logging.Warn(ctx, "checkpoint migration skipped v1 sessions with missing transcript/session content",
513				slog.String("checkpoint_id", string(info.CheckpointID)),
514				slog.Int("missing_sessions", skippedMissingSessions),
515			)
516		}
517	
518		return fullCheckpoint, outcome, nil
519	}
