550		}
551	
552		// Evict any pre-existing raw transcript artifacts for the sessions we're
553		// about to write so a shrinking chunk count can't leave stale .N files
554		// behind from a prior migration of the same checkpoint.
555		for _, cp := range checkpoints {
556			for _, session := range cp.sessions {
557				evictMigratedRawArtifacts(entries, cp.checkpointID, session.sessionIndex)
