83	// acquireCommandLock takes <git-common-dir>/<lockFile> as a per-command
84	// exclusive lock. On contention it prints a message to stderr and returns a
85	// SilentError. Other setup failures return regular errors so main.go prints
86	// them. Defer release() after logging.Init so a release error can still be
87	// warned (LIFO defer order).
88	func acquireCommandLock(ctx context.Context, cmd *cobra.Command, lockFile, opName string) (release func(), err error) {
89		commonDir, err := strategy.GetGitCommonDir(ctx)
90		if err != nil {
91			cmd.SilenceUsage = true
92			return nil, fmt.Errorf("resolve git common dir: %w", err)
93		}
94		lockPath := filepath.Join(commonDir, lockFile)
95	
96		lk, err := lockfile.Acquire(lockPath)
97		if err != nil {
98			if errors.Is(err, lockfile.ErrLocked) {
99				cmd.SilenceUsage = true
100				pidStr := "unknown"
101				if holder := lockfile.ReadHolderPID(lockPath); holder > 0 {
102					pidStr = strconv.Itoa(holder)
103				}
104				fmt.Fprintf(cmd.ErrOrStderr(),
105					"another `entire %s` is already running (PID %s, lock at %s); refusing to start a second instance\n",
106					opName, pidStr, lockPath)
107				return nil, NewSilentError(fmt.Errorf("%s already in progress", opName))
108			}
109			cmd.SilenceUsage = true
110			return nil, fmt.Errorf("acquire %s lock: %w", opName, err)
111		}
112	
113		return func() {
114			if relErr := lk.Release(); relErr != nil {
115				logging.Warn(ctx, "failed to release command lock",
116					slog.String("op", opName),
117					slog.String("error", relErr.Error()))
118			}
119		}, nil
120	}
