package cli

import (
	"bytes"
	"context"
	"strings"
	"testing"
	"time"
)

func TestFormatProfileDuration(t *testing.T) {
	t.Parallel()
	tests := []struct {
		name string
		in   time.Duration
		want string
	}{
		{"zero", 0, "0ms"},
		{"sub-second integer ms", 142 * time.Millisecond, "142ms"},
		{"just under a second", 999 * time.Millisecond, "999ms"},
		{"one second exact", time.Second, "1.0s"},
		{"low seconds with fraction", 1400 * time.Millisecond, "1.4s"},
		{"under ten seconds", 9200 * time.Millisecond, "9.2s"},
		{"ten seconds rounds to integer", 12 * time.Second, "12s"},
		{"under a minute", 42 * time.Second, "42s"},
		{"minute boundary", 60 * time.Second, "1m0s"},
		{"minutes and seconds", 72 * time.Second, "1m12s"},
		{"larger minutes", 22*time.Minute + 13*time.Second, "22m13s"},
		{"one hour exact", time.Hour, "1h0m"},
		{"hours and minutes", time.Hour + 5*time.Minute, "1h5m"},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			t.Parallel()
			if got := formatProfileDuration(tt.in); got != tt.want {
				t.Errorf("formatProfileDuration(%v) = %q, want %q", tt.in, got, tt.want)
			}
		})
	}
}

func TestMigrateProfiler_RenderEmpty(t *testing.T) {
	t.Parallel()
	p := newMigrateProfiler()
	var buf bytes.Buffer
	p.render(&buf)
	got := buf.String()
	if got != "" {
		t.Errorf("expected empty output for empty profiler, got %q", got)
	}
}

func TestMigrateProfiler_RecordsPhase(t *testing.T) {
	t.Parallel()
	p := newMigrateProfiler()
	p.recordPhase("list_v1_checkpoints", 142*time.Millisecond)
	p.recordPhase("process_checkpoints", 22*time.Minute+8*time.Second)

	var buf bytes.Buffer
	p.render(&buf)
	got := buf.String()

	if !strings.Contains(got, "PHASE") || !strings.Contains(got, "DURATION") {
		t.Fatalf("missing phase header in output:\n%s", got)
	}
	if !strings.Contains(got, "list_v1_checkpoints") || !strings.Contains(got, "142ms") {
		t.Errorf("missing list_v1_checkpoints/142ms in output:\n%s", got)
	}
	if !strings.Contains(got, "process_checkpoints") || !strings.Contains(got, "22m8s") {
		t.Errorf("missing process_checkpoints/22m8s in output:\n%s", got)
	}

	// Phase order should match insertion order.
	listIdx := strings.Index(got, "list_v1_checkpoints")
	procIdx := strings.Index(got, "process_checkpoints")
	if listIdx == -1 || procIdx == -1 || listIdx > procIdx {
		t.Errorf("phases not in insertion order:\n%s", got)
	}
}

func TestMigrateProfiler_AggregatesStage(t *testing.T) {
	t.Parallel()
	p := newMigrateProfiler()
	p.recordStage("read_v2_existing", 3*time.Millisecond)
	p.recordStage("read_v2_existing", 5*time.Millisecond)
	p.recordStage("read_v2_existing", 45*time.Millisecond) // max

	var buf bytes.Buffer
	p.render(&buf)
	got := buf.String()

	if !strings.Contains(got, "STAGE") || !strings.Contains(got, "COUNT") ||
		!strings.Contains(got, "TOTAL") || !strings.Contains(got, "AVG") || !strings.Contains(got, "MAX") {
		t.Fatalf("missing stage header columns:\n%s", got)
	}

	// Find the stage row.
	var stageLine string
	for _, line := range strings.Split(got, "\n") {
		if strings.Contains(line, "read_v2_existing") {
			stageLine = line
			break
		}
	}
	if stageLine == "" {
		t.Fatalf("missing read_v2_existing row:\n%s", got)
	}

	// count=3, total=53ms, avg=17ms (53/3 truncated), max=45ms.
	for _, want := range []string{"3", "53ms", "17ms", "45ms"} {
		if !strings.Contains(stageLine, want) {
			t.Errorf("stage line missing %q: %q", want, stageLine)
		}
