func TestMigrateProfiler_StageOrderPreserved(t *testing.T) {
	t.Parallel()
	p := newMigrateProfiler()
	// Insert in non-alphabetic order.
	p.recordStage("write_v2_session", 10*time.Millisecond)
	p.recordStage("read_v1_summary", 5*time.Millisecond)
	p.recordStage("compact_transcript", 20*time.Millisecond)

	var buf bytes.Buffer
	p.render(&buf)
	got := buf.String()

	wIdx := strings.Index(got, "write_v2_session")
	rIdx := strings.Index(got, "read_v1_summary")
	cIdx := strings.Index(got, "compact_transcript")
	if wIdx == -1 || rIdx == -1 || cIdx == -1 {
		t.Fatalf("missing stage rows:\n%s", got)
	}
	if !(wIdx < rIdx && rIdx < cIdx) {
		t.Errorf("stages not in insertion order (got w=%d r=%d c=%d):\n%s", wIdx, rIdx, cIdx, got)
	}
}

