package cli

import (
	"context"
	"fmt"
	"io"
	"time"
)

// migrateProfiler tracks timing for `entire migrate --profile`. It distinguishes
// two kinds of measurements:
//
//   - Phases: one-shot wall-clock segments (e.g., listing v1 checkpoints,
//     packing the partial generation). Each call to recordPhase appends a row.
//   - Stages: per-iteration segments inside the migration loop, aggregated
//     across thousands of calls into count/total/avg/max so the report stays
//     a fixed size regardless of checkpoint count.
type migrateProfiler struct {
	phases     []phaseRecord
	stages     map[string]*stageStat
	stageOrder []string
}

type phaseRecord struct {
	name     string
	duration time.Duration
}

type stageStat struct {
	name  string
	count int
	total time.Duration
	max   time.Duration
}

func newMigrateProfiler() *migrateProfiler {
	return &migrateProfiler{stages: make(map[string]*stageStat)}
}

func (p *migrateProfiler) recordPhase(name string, dur time.Duration) {
	if p == nil {
		return
	}
	p.phases = append(p.phases, phaseRecord{name: name, duration: dur})
}

func (p *migrateProfiler) recordStage(name string, dur time.Duration) {
	if p == nil {
		return
	}
	s, ok := p.stages[name]
	if !ok {
		s = &stageStat{name: name}
		p.stages[name] = s
		p.stageOrder = append(p.stageOrder, name)
	}
	s.count++
	s.total += dur
	if dur > s.max {
		s.max = dur
	}
}

func (p *migrateProfiler) phaseCount() int { return len(p.phases) }

func (p *migrateProfiler) stageCount(name string) int {
	if s, ok := p.stages[name]; ok {
		return s.count
	}
	return 0
}

func (p *migrateProfiler) stageTotal(name string) time.Duration {
	if s, ok := p.stages[name]; ok {
		return s.total
	}
	return 0
}

func (p *migrateProfiler) render(w io.Writer) {
	if p == nil || (len(p.phases) == 0 && len(p.stageOrder) == 0) {
		return
	}
	if len(p.phases) > 0 {
		p.renderPhases(w)
	}
	if len(p.stageOrder) > 0 {
		if len(p.phases) > 0 {
			fmt.Fprintln(w)
		}
		p.renderStages(w)
	}
}

func (p *migrateProfiler) renderPhases(w io.Writer) {
	nameWidth := len("PHASE")
	durWidth := len("DURATION")
	for _, ph := range p.phases {
		if n := len(ph.name); n > nameWidth {
			nameWidth = n
		}
		if d := len(formatProfileDuration(ph.duration)); d > durWidth {
			durWidth = d
		}
	}
	fmt.Fprintf(w, "%-*s  %*s\n", nameWidth, "PHASE", durWidth, "DURATION")
	for _, ph := range p.phases {
		fmt.Fprintf(w, "%-*s  %*s\n", nameWidth, ph.name, durWidth, formatProfileDuration(ph.duration))
	}
}

func (p *migrateProfiler) renderStages(w io.Writer) {
	nameWidth := len("STAGE")
	countWidth := len("COUNT")
	totalWidth := len("TOTAL")
	avgWidth := len("AVG")
	maxWidth := len("MAX")
	for _, name := range p.stageOrder {
		s := p.stages[name]
		avg := stageAverage(s)
		if n := len(name); n > nameWidth {
			nameWidth = n
		}
		if c := len(fmt.Sprintf("%d", s.count)); c > countWidth {
			countWidth = c
		}
		if t := len(formatProfileDuration(s.total)); t > totalWidth {
			totalWidth = t
		}
		if a := len(formatProfileDuration(avg)); a > avgWidth {
			avgWidth = a
		}
		if m := len(formatProfileDuration(s.max)); m > maxWidth {
			maxWidth = m
		}
	}
	fmt.Fprintf(w, "%-*s  %*s  %*s  %*s  %*s\n",
		nameWidth, "STAGE",
		countWidth, "COUNT",
		totalWidth, "TOTAL",
		avgWidth, "AVG",
		maxWidth, "MAX")
	for _, name := range p.stageOrder {
		s := p.stages[name]
		fmt.Fprintf(w, "%-*s  %*d  %*s  %*s  %*s\n",
			nameWidth, name,
			countWidth, s.count,
			totalWidth, formatProfileDuration(s.total),
			avgWidth, formatProfileDuration(stageAverage(s)),
			maxWidth, formatProfileDuration(s.max))
	}
}

func stageAverage(s *stageStat) time.Duration {
	if s.count == 0 {
		return 0
	}
	return time.Duration(int64(s.total) / int64(s.count))
}

type profilerCtxKey struct{}

func contextWithProfiler(ctx context.Context, p *migrateProfiler) context.Context {
	return context.WithValue(ctx, profilerCtxKey{}, p)
}

func profilerFromContext(ctx context.Context) *migrateProfiler {
	p, _ := ctx.Value(profilerCtxKey{}).(*migrateProfiler)
	return p
}

// profileStartPhase records a phase duration on stop. Returns a no-op closure
// when no profiler is attached to ctx.
func profileStartPhase(ctx context.Context, name string) func() {
	p := profilerFromContext(ctx)
	if p == nil {
		return func() {}
	}
	start := time.Now()
	return func() { p.recordPhase(name, time.Since(start)) }
}

// profileStartStage records a stage duration on stop. Returns a no-op closure
// when no profiler is attached to ctx.
func profileStartStage(ctx context.Context, name string) func() {
	p := profilerFromContext(ctx)
	if p == nil {
		return func() {}
	}
	start := time.Now()
	return func() { p.recordStage(name, time.Since(start)) }
}

// formatProfileDuration formats a duration with adaptive precision:
//   - <1s: integer milliseconds ("142ms")
//   - 1s..10s: one decimal place ("1.4s", "9.2s")
//   - 10s..60s: integer seconds ("12s", "42s")
//   - 1m..1h: minutes and seconds ("22m13s")
//   - >=1h: hours and minutes ("1h5m")
func formatProfileDuration(d time.Duration) string {
	switch {
	case d < time.Second:
		return fmt.Sprintf("%dms", d.Milliseconds())
	case d < 10*time.Second:
		return fmt.Sprintf("%.1fs", d.Seconds())
	case d < time.Minute:
		return fmt.Sprintf("%ds", int(d.Seconds()))
	case d < time.Hour:
		m := int(d / time.Minute)
		s := int((d % time.Minute) / time.Second)
		return fmt.Sprintf("%dm%ds", m, s)
	default:
		h := int(d / time.Hour)
		m := int((d % time.Hour) / time.Minute)
		return fmt.Sprintf("%dh%dm", h, m)
	}
}

