// TestMigrateCheckpointsV2_ProfilerCapturesPhasesAndStages verifies the profiler
// instrumentation in the migration path actually fires when a profiler is in
// context — i.e., phases and per-checkpoint stages are recorded with counts
// matching the number of v1 checkpoints/sessions migrated.
func TestMigrateCheckpointsV2_ProfilerCapturesPhasesAndStages(t *testing.T) {
	t.Parallel()
	repo := initMigrateTestRepo(t)
	v1Store, v2Store := newMigrateStores(repo)

	transcript := []byte("{\"type\":\"assistant\",\"message\":\"hello\"}\n")
	for i, cpID := range []id.CheckpointID{
		id.MustCheckpointID("aa11bb22cc33"),
		id.MustCheckpointID("dd44ee55ff66"),
	} {
		writeV1Checkpoint(t, v1Store, cpID, "session-prof-"+string(rune('a'+i)), transcript, []string{"prompt"})
	}

	p := newMigrateProfiler()
	ctx := contextWithProfiler(context.Background(), p)
	var stdout bytes.Buffer

	result, _, err := migrateCheckpointsV2(ctx, repo, v1Store, v2Store, &stdout, false)
	require.NoError(t, err)
	require.Equal(t, 2, result.migrated)

	// Phases run once each.
	if p.phaseCount() < 2 {
		t.Errorf("expected at least 2 phases (list + index), got %d", p.phaseCount())
	}

	// Per-checkpoint stages: each fires once per v1 checkpoint.
	for _, name := range []string{"read_v2_existing", "read_v1_summary"} {
		if got := p.stageCount(name); got != 2 {
			t.Errorf("stage %q count = %d, want 2", name, got)
		}
	}
	// Per-session stages: one session per checkpoint here, so also 2.
	for _, name := range []string{"read_v1_session", "compact_transcript", "write_v2_session"} {
		if got := p.stageCount(name); got != 2 {
			t.Errorf("stage %q count = %d, want 2", name, got)
		}
	}

	// Render produces output with both PHASE and STAGE sections.
	var report bytes.Buffer
	p.render(&report)
	if !strings.Contains(report.String(), "PHASE") || !strings.Contains(report.String(), "STAGE") {
		t.Errorf("rendered profile missing PHASE or STAGE section:\n%s", report.String())
	}
}

